@login_required
@require_POST
def follow_view(request, username):
    profile_user = get_object_or_404(User, username=username)
    # A block in either direction disables following.
    blocked = request.user.has_blocked(profile_user) or profile_user.has_blocked(request.user)
    if profile_user != request.user and not blocked:
        if profile_user.followers.filter(pk=request.user.id).exists():
            profile_user.followers.remove(request.user)
            is_following = False
        else:
            profile_user.followers.add(request.user)
            is_following = True
    else:
        is_following = request.user.is_following(profile_user)
    if is_htmx(request):
        return render(
            request,
            "partials/follow_button.html",
            {
                "profile_user": profile_user,
                "is_following": is_following,
            },
        )
    return redirect("profile", username=username)


@login_required
@require_POST
def block_view(request, username):
    profile_user = get_object_or_404(User, username=username)
    if profile_user != request.user:
        if request.user.blocked.filter(pk=profile_user.id).exists():
            request.user.blocked.remove(profile_user)
        else:
            request.user.blocked.add(profile_user)
            # Blocking severs any existing follow relationship in both directions.
            profile_user.followers.remove(request.user)
            request.user.followers.remove(profile_user)

    from_list = request.POST.get("source") == "list"
    if is_htmx(request):
        if from_list:
            # Row is removed from the blocked-users management list.
            return HttpResponse("")
        return render(
            request,
            "partials/profile_actions.html",
            {
                "profile_user": profile_user,
                "is_following": request.user.is_following(profile_user),
            },
        )
    return redirect("blocked_users") if from_list else redirect("profile", username=username)


@login_required
def blocked_users_view(request):
    blocked_users = request.user.blocked.order_by("username")
    return render(request, "accounts/blocked_users.html", {"blocked_users": blocked_users})
